void CinemaSpiMaster::end() {
#ifdef ARDUINO_ARCH_ESP32
  if (_rightDevice) spi_bus_remove_device(static_cast<spi_device_handle_t>(_rightDevice));
  if (_leftDevice) spi_bus_remove_device(static_cast<spi_device_handle_t>(_leftDevice));
  if (_busInitialized) spi_bus_free(SPI2_HOST);
  if (_rxBuffer) heap_caps_free(_rxBuffer);
  if (_txBuffer) heap_caps_free(_txBuffer);
#endif
  _rightDevice = nullptr;
  _leftDevice = nullptr;
  _rxBuffer = nullptr;
  _txBuffer = nullptr;
  _busInitialized = false;
  releasePins();
  _lastPollMillis = 0;
  _slotSequence = 0;
  _leftPolls = 0;
  _rightPolls = 0;
  _validSlots = 0;
  _slotErrors = 0;
  _transferErrors = 0;
  _lastDiagnosticsMillis = 0;
  _pollLeft = true;
  _status = CinemaSpiStatus::Disabled;
}

bool CinemaSpiMaster::poll(protocol::PacketView* packet, protocol::NodeRole* expectedSource, uint32_t nowMillis) {
  if (!packet || !expectedSource || !isReady() || static_cast<uint32_t>(nowMillis - _lastPollMillis) < SPI_POLL_INTERVAL_MS) return false;
  _lastPollMillis = nowMillis;

#ifdef ARDUINO_ARCH_ESP32
  if (spi::encodeSlot(nullptr, 0, 0, ++_slotSequence, _txBuffer, spi::SLOT_SIZE) != spi::SlotStatus::Ok) return false;

  spi_transaction_t transaction = {};
  transaction.length = spi::SLOT_SIZE * 8;
  transaction.rxlength = spi::SLOT_SIZE * 8;
  transaction.tx_buffer = _txBuffer;
  transaction.rx_buffer = _rxBuffer;
  const bool pollingLeft = _pollLeft;
  spi_device_handle_t device = static_cast<spi_device_handle_t>(pollingLeft ? _leftDevice : _rightDevice);
  _pollLeft = !_pollLeft;
  if (pollingLeft) _leftPolls++;
  else _rightPolls++;
  // This dedicated host has no outstanding transfers; switch only while both CS lines are idle.
  const int8_t misoPin = pollingLeft ? _config.misoPin : _config.rightMisoPin;
  esp_rom_gpio_connect_in_signal(misoPin, spi_periph_signal[SPI2_HOST].spiq_in, false);
  if (!device || spi_device_transmit(device, &transaction) != ESP_OK) {
    _transferErrors++;
    reportDiagnostics(nowMillis);
    return false;
  }

  spi::SlotView slot;
  if (spi::decodeSlot(_rxBuffer, spi::SLOT_SIZE, &slot) != spi::SlotStatus::Ok) {
    _slotErrors++;
    reportDiagnostics(nowMillis);
    return false;
  }
  _validSlots++;
  reportDiagnostics(nowMillis);
  *packet = slot.packet;
  *expectedSource = pollingLeft ? protocol::NodeRole::CameraLeft : protocol::NodeRole::CameraRight;
  return true;
#else
  return false;
#endif
}

void CinemaSpiMaster::reportDiagnostics(uint32_t nowMillis) {
  if (static_cast<uint32_t>(nowMillis - _lastDiagnosticsMillis) < 1000) return;
  _lastDiagnosticsMillis = nowMillis;
  DEBUG_PRINTF("Cinema SPI master: polls L/R=%lu/%lu valid=%lu slot-errors=%lu transfer-errors=%lu\n",
    static_cast<unsigned long>(_leftPolls), static_cast<unsigned long>(_rightPolls), static_cast<unsigned long>(_validSlots),
    static_cast<unsigned long>(_slotErrors), static_cast<unsigned long>(_transferErrors));
}

void CinemaSpiMaster::releasePins() {
  if (!_pinsAllocated) return;
  const managed_pin_type pins[] = {
    {_config.sclkPin, true},
    {_config.mosiPin, true},
    {_config.misoPin, false},
    {_config.rightMisoPin, false},
    {_config.leftCsPin, true},
    {_config.rightCsPin, true}
  };
  PinManager::deallocateMultiplePins(pins, sizeof(pins) / sizeof(pins[0]), PinOwner::Cinema);
  _pinsAllocated = false;
}

